VM_TEST = "const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');\nconst root=process.argv[1], nodes=new Map(), handlers={};\nclass Element{\n constructor(id=''){this.id=id;this.value='';this.disabled=false;this.hidden=false;this.children=[];this.events={};this.dataset={};this._html='';this.textContent='';const classes=new Set();this.classList={add:x=>classes.add(x),remove:x=>classes.delete(x),contains:x=>classes.has(x),toggle:(x,force)=>{const next=force===undefined?!classes.has(x):force;if(next)classes.add(x);else classes.delete(x);return next;}};}\n set innerHTML(value){this._html=value;}get innerHTML(){return this._html;}\n addEventListener(type,fn){(this.events[type]??=[]).push(fn);}\n append(...children){this.children.push(...children);}remove(){}click(){this.clicked=true;}showModal(){this.open=true;}close(){this.open=false;}scrollIntoView(){this.scrolled=true;}\n}\nconst element=id=>{if(!nodes.has(id))nodes.set(id,new Element(id));return nodes.get(id);};\nconst html=fs.readFileSync(path.join(root,'frontend/index.html'),'utf8');\nfor(const m of html.matchAll(/\\bid=\"([^\"]+)\"/g))element(m[1]);\nelement('filter-lang').value='all';element('filter-status').value='all';\nconst document={getElementById:id=>id==='call-audio'&&!element('dialog-detail-container').innerHTML.includes('<audio ')?null:element(id),querySelectorAll:()=>[],createElement:()=>new Element(),body:new Element('body'),documentElement:new Element('html'),addEventListener:(name,fn)=>(handlers[name]??=[]).push(fn)};\nconst configs=['contact','discovery','identification','consultation','empathy','dialogue','closure','critical'].map((id,i)=>({criterion_id:id,label:id,description:'Rule for '+id,weight:[10,15,20,20,15,15,5,0][i],answer_type:['consultation','dialogue'].includes(id)?'scale':'boolean',allow_na:['discovery','identification','consultation','closure'].includes(id),scale:id==='consultation'?[0,5,10,15,20]:id==='dialogue'?[0,4,7,10]:[]}));\nconst model={mode:'local',name:'fixture-only-model'}, checklists=[{id:'default',name:'Official checklist',version:1,criteria:configs}];\nlet groups=[],ready=false,settings={team_name:'red_rider',model_name:'',model_mode:'local',model_base_url:'http://127.0.0.1:1234/v1',api_key_configured:true,dataset_api_configured:false},calls=[],records={};\nfunction record(group,id,scored=false,critical=false){\n const conversation={conversation_id:id,channel:'agent chat',language:'RU',audio_url:null,transcript:[{timestamp:'00:00',speaker:'client',text:'<img src=x onerror=alert(1)>'},{timestamp:'00:02',speaker:'operator',text:'Здравствуйте! Я Анна.'},{timestamp:'00:04',speaker:'bot',text:'Контекст бота'},{timestamp:'00:06',speaker:'system',text:'Чат завершён'}]};\n const criteria=configs.map(c=>({criterion_id:c.criterion_id,value:c.criterion_id==='critical'?critical:c.criterion_id==='identification'?null:c.answer_type==='boolean'?true:c.scale.at(-1),rationale:'<script>unsafe</script> checked '+c.criterion_id,evidence_turns:c.criterion_id==='identification'?[1]:[2]}));\n const result=scored?{conversation_id:id,status:'ok',criteria,score:{final_score:100,critical_flag:critical}}:null;\n return {group_id:group,evaluation_id:'eval-'+id,conversation,original_result:structuredClone(result),final_result:structuredClone(result),checklist:structuredClone(checklists[0]),model:scored?model:null,appeals:[]};\n}\nfunction seed(){groups=[{group_id:'DEMO',total_records:1},{group_id:'DEV',total_records:65},{group_id:'CONTROL',total_records:10}];records.DEMO=[record('DEMO','demo-source-1',true,true)];records.DEV=Array.from({length:65},(_,i)=>record('DEV','real-dev-'+i));records.CONTROL=Array.from({length:10},(_,i)=>record('CONTROL','real-control-'+i));}\nfunction resultResponse(data,status=200){return {ok:status<400,status,json:async()=>structuredClone(data),blob:async()=>new Blob([JSON.stringify(data)],{type:'application/json'})};}\nasync function fetchMock(raw,options={}){\n const u=new URL(raw,'http://local.test'),route=u.pathname,method=options.method||'GET',body=options.body?JSON.parse(options.body):null;\n calls.push({route,method,body,query:Object.fromEntries(u.searchParams)});\n const group=u.searchParams.get('group_id');\n if(route==='/api/health')return resultResponse({status:'ok',model_configured:ready,model_name:settings.model_name,dataset_api_configured:false});\n if(route==='/api/settings'){if(method==='PUT'){Object.assign(settings,body);ready=!!settings.model_name;}return resultResponse(settings);}\n if(route==='/api/datasets')return resultResponse(groups);\n if(route==='/api/demo'){seed();return resultResponse({group_id:'DEMO',total_records:1});}\n if(route==='/api/checklists'){if(method==='POST'){checklists.push(structuredClone(body));return resultResponse(body);}return resultResponse(checklists);}\n if(route.startsWith('/api/checklists/')){const index=checklists.findIndex(c=>c.id===decodeURIComponent(route.split('/').at(-1)));if(method==='PUT'){body.version++;checklists[index]=structuredClone(body);}return resultResponse(checklists[index]);}\n if(route==='/api/conversations')return resultResponse((records[group]||[]).map(r=>({conversation_id:r.conversation.conversation_id,channel:r.conversation.channel,language:r.conversation.language,turns:r.conversation.transcript.length,status:r.final_result?.status||'pending',final_score:r.final_result?.score?.final_score??null,critical_flag:r.final_result?.score?.critical_flag||false,appeals_pending:r.appeals.filter(a=>a.status==='pending').length})));\n if(route==='/api/evaluations'){\n   assert.equal(body.retry_errors_only,false,'full-batch action must reevaluate prior ok rows');\n   if(!ready)return resultResponse({detail:'Configure model in Connections'},503);\n   for(const r of records[body.group_id]){const completed=record(body.group_id,r.conversation.conversation_id,true);Object.assign(r,completed);}\n   return resultResponse({group_id:body.group_id,total:records[body.group_id].length,completed:records[body.group_id].length,failed:0});\n }\n if(/^\\/api\\/conversations\\/[^/]+\\/evaluate$/.test(route))return resultResponse({detail:'Configure model in Connections'},503);\n if(/^\\/api\\/conversations\\/[^/]+\\/appeals$/.test(route)){\n   const id=decodeURIComponent(route.split('/')[3]),r=records[body.group_id].find(r=>r.conversation.conversation_id===id);\n   const a={id:'appeal-1',group_id:body.group_id,conversation_id:id,evaluation_id:r.evaluation_id,criterion_id:body.criterion_id,comment:body.comment,status:'pending',decision:null};r.appeals.push(a);return resultResponse(a,201);\n }\n if(/^\\/api\\/appeals\\/[^/]+\\/decision$/.test(route)){\n   const r=Object.values(records).flat().find(r=>r.appeals.some(a=>a.id==='appeal-1')),a=r.appeals[0];\n   a.status='resolved';a.decision={action:body.decision,reason:body.reason};\n   if(body.replacement){r.final_result.criteria=r.final_result.criteria.map(c=>c.criterion_id===body.replacement.criterion_id?body.replacement:c);r.final_result.score.final_score=88;}\n   return resultResponse({appeal:a,record:r});\n }\n if(route.startsWith('/api/conversations/')){const id=decodeURIComponent(route.split('/')[3]);return resultResponse(records[group].find(r=>r.conversation.conversation_id===id));}\n if(route==='/api/results/export'){\n   const rows=records[group]||[],required=u.searchParams.get('subset')==='dev'?65:10;\n   if(group==='DEMO'||rows.length!==required||rows.some(r=>!r.final_result))return resultResponse({detail:'Incomplete or demonstration results'},422);\n   return resultResponse({schema_version:'1.0',team_name:settings.team_name,model,results:rows.map(r=>r.final_result)});\n }\n if(route==='/api/results/save'){assert.equal(body.subset,'prod');assert.equal(body.group_id,'CONTROL');return resultResponse({saved:true,path:'results/prod/results.json',records:10});}\n throw new Error('Unexpected frontend API request: '+method+' '+raw);\n}\nconst localStore=new Map();\nclass FormDataFixture{constructor(form){this.values=form.values;}get(key){return this.values[key]??null;}}\nconst context=vm.createContext({document,fetch:fetchMock,localStorage:{getItem:k=>localStore.get(k)||null,setItem:(k,v)=>localStore.set(k,v)},navigator:{clipboard:{writeText:async text=>{context.copied=text;}}},URL,URLSearchParams,FormData:FormDataFixture,Blob,Intl,console,structuredClone,Date,Number,JSON,setTimeout:()=>0,clearTimeout:()=>{},});\nvm.runInContext(fs.readFileSync(path.join(root,'frontend/i18n.js'),'utf8'),context);\nvm.runInContext(fs.readFileSync(path.join(root,'frontend/app.js'),'utf8'),context);\nconst flush=async()=>{for(let i=0;i<40;i++)await Promise.resolve();};\nconst action=async(name,data={})=>{const node={dataset:{action:name,...data}};for(const fn of handlers.click||[])await fn({target:{closest:()=>node}});await flush();};\nconst click=async id=>{for(const fn of element(id).events.click||[])await fn({target:element(id)});await flush();};\nconst change=async(id,value)=>{const node=element(id);node.value=value;for(const fn of node.events.change||[])await fn({target:node});for(const fn of handlers.change||[])await fn({target:node});await flush();};\nconst submit=async(id,values)=>{for(const fn of handlers.submit||[])await fn({target:{id,values},preventDefault(){}});await flush();};\n(async()=>{\n await flush();\n assert.equal(calls.some(c=>c.route==='/api/demo'),false,'demo must require explicit action');\n assert.match(element('dialog-detail-container').innerHTML,/QACore AI/);\n await action('demo');\n assert.match(element('global-demo').innerHTML,/ИИ не вызывался/);\n assert.match(element('dialog-list-container').innerHTML,/demo-source-1/);\n const detail=element('dialog-detail-container').innerHTML;\n assert.match(detail,/&lt;img src=x onerror=alert\\(1\\)&gt;/,'source turns must be escaped');\n assert.doesNotMatch(detail,/<img src=x/);\n assert.doesNotMatch(detail,/<audio|\\/null/,'null audio must not produce a player');\n assert.match(detail,/critical<\\/h3><span class=\"qa-pill qa-danger\"/,'critical:true must be marked as a violation');\n assert.match(detail,/вес исключён/,'N/A weights must be explicitly excluded');\n await action('evidence',{turn:'2'});assert.equal(element('utt-2').scrolled,true);\n await action('appeal',{criterion:'contact'});await submit('appeal-form',{comment:'Review the original full turn'});\n assert.equal(calls.find(c=>c.route.endsWith('/appeals')).body.criterion_id,'contact');\n await action('review',{appeal:'appeal-1'});await change('review-decision','change');\n assert.equal(element('review-change-fields').hidden,false,'change decision must reveal editable fields');\n await submit('review-form',{decision:'change',value:'false',rationale:'Reviewed original turn',evidence:'2, 4',reason:'Evidence reviewed'});\n const decisionCall=calls.find(c=>c.route.endsWith('/decision'));\n assert.deepEqual(decisionCall.body.replacement.evidence_turns,[2,4]);\n assert.equal(decisionCall.body.replacement.value,false);\n assert.equal(records.DEMO[0].original_result.criteria[0].value,true,'review cannot alter original result');\n await click('nav-checklist');await action('new-checklist');await action('add-criterion');await click('btn-save-checklist');\n const newChecklist=calls.find(c=>c.route==='/api/checklists'&&c.method==='POST');\n assert.equal(newChecklist.body.criteria.length,9,'additional criteria must be saved to server');\n assert.equal(newChecklist.body.criteria.at(-1).criterion_id,'criterion_9');\n await change('active-checklist','default');\n await click('nav-workspace');await change('filter-dataset','CONTROL');\n await action('evaluate');\n assert.match(element('toast-container').children.at(-1).textContent,/Configure model/,'unconfigured model must show server failure');\n assert.equal(records.CONTROL[0].final_result,null,'no fake assessment after a failed request');\n await action('settings');\n await submit('settings-form',{team_name:'red_rider',model_name:'fixture-only-model',model_mode:'local',model_base_url:'http://127.0.0.1:1234/v1',model_api_key:'',dataset_api_url:''});\n const settingsCall=calls.find(c=>c.route==='/api/settings'&&c.method==='PUT');\n assert.equal('model_api_key' in settingsCall.body,false,'blank key must preserve stored secret');\n assert.equal('dataset_api_url' in settingsCall.body,false);\n await click('btn-evaluate-all');\n assert.equal(calls.filter(c=>c.route==='/api/evaluations').at(-1).body.retry_errors_only,false);\n assert.equal(records.CONTROL.filter(r=>r.final_result).length,10);\n await click('nav-export');\n await change('export-dev-group','DEV');await change('export-prod-group','CONTROL');\n await click('btn-run-validation');\n assert.match(element('validation-cards-grid').innerHTML,/10 \\/ 10/);\n await change('export-prod-group','DEV');\n assert.doesNotMatch(element('validation-cards-grid').innerHTML,/10 \\/ 10/,'verification must not survive a group switch');\n await change('export-prod-group','CONTROL');\n await click('btn-download-prod');\n const saved=calls.find(c=>c.route==='/api/results/save');\n assert.deepEqual(saved.body,{group_id:'CONTROL',subset:'prod',team_name:'red_rider'});\n const saveIndex=calls.indexOf(saved);\n assert.equal(calls[saveIndex+1].route,'/api/results/export','server save must precede downloaded copy');\n assert.equal([...localStore.keys()].some(k=>/key|token|secret/i.test(k)),false);\n console.log(JSON.stringify({passed:true,assertions:25,requests:calls.length,scenarios:['explicit demo','XSS escaping','null audio','critical flag','full-turn evidence','appeal review','original result','custom criterion','missing model','safe settings','full batch','strict save/export','stale validation']}));\n})().catch(error=>{console.error(error.stack);process.exitCode=1;});\n"

class FrontendContractTests(unittest.TestCase):
    @unittest.skipUnless(NODE, 'Node.js is optional for frontend contract tests')
    def test_connected_lifecycle_contract_and_failure_states(self):
        result = subprocess.run([NODE, '-e', VM_TEST, str(ROOT)], capture_output=True, text=True, encoding='utf-8', timeout=30, creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertIn('"passed":true', result.stdout)

    def test_offline_assets_and_no_mock_submission_engine(self):
        html = (ROOT / 'frontend/index.html').read_text(encoding='utf-8')
        app = (ROOT / 'frontend/app.js').read_text(encoding='utf-8')
        self.assertIn('QACore AI', html)
        self.assertIn('nav-workspace', html)
        self.assertNotIn('cdn.tailwindcss.com', html)
        self.assertNotIn('fonts.googleapis.com', html)
        self.assertNotIn('buildFullDatasetPayload', app)
        self.assertNotIn('createOscillator', app)
        self.assertNotIn('DLG-DEV-001', app)
        for asset in ['app.js','i18n.js','qacore.css','styles.css']:
            self.assertTrue((ROOT / 'frontend' / asset).is_file())

if __name__ == '__main__':
    unittest.main()
